settings.custom_css:
/* Pill buttons for all homepage sections (needs Elementor Pro Custom CSS). Not scoped, so it styles every .gw-pill on the page. */
.gw-pill .elementor-button { display: inline-flex; align-items: center; min-height: 52px; transition: opacity .3s; }
.gw-pill .elementor-button:hover { opacity: .85; }
.gw-pill .elementor-button-content-wrapper { align-items: center; }
.gw-pill .elementor-button-icon svg { width: 16px; height: auto; }
.gw-pill--primary .elementor-button-icon, .gw-pill--light .elementor-button-icon { display: flex; align-items: center; justify-content: center; width: 40px; height: 40px; border-radius: 50%; }
.gw-pill--primary .elementor-button-icon { background: #FFFFFF; }
.gw-pill--light .elementor-button-icon { background: #0074BE; }
/* Glacier West overflow safety, 980-1440px (Elementor Pro Custom CSS). Mirrors the _laptop values, so it also works
   when the Laptop breakpoint is NOT enabled in Site Settings > Layout > Breakpoints. Scoped to .gw-sec sections only. */
.gw-sec .e-con, .gw-sec .elementor-widget { min-width: 0; }
.gw-sec .elementor-heading-title, .gw-sec .elementor-widget-text-editor { overflow-wrap: break-word; }
@media (min-width: 1025px) and (max-width: 1366px) {
  .gw-sec > .gw-inner { padding-left: 48px !important; padding-right: 48px !important; }
  .gw-sec .gw-gap-lg { column-gap: 40px !important; }
  .gw-sec .gw-wwb-panel { margin-right: -48px !important; padding: 96px 48px 56px 32px !important; }
  .gw-sec .gw-pad-lg { padding-left: 48px !important; padding-right: 48px !important; }
  .gw-sec .gw-fs-xl .elementor-heading-title, .gw-sec .gw-fs-xl.elementor-widget-text-editor, .gw-sec .gw-fs-xl .elementor-widget-container { font-size: 52px !important; line-height: 1.05 !important; }
  .gw-sec .gw-fs-lg .elementor-heading-title, .gw-sec .gw-fs-lg.elementor-widget-text-editor, .gw-sec .gw-fs-lg .elementor-widget-container { font-size: 44px !important; line-height: 1.2 !important; }
  .gw-sec .gw-fs-md .elementor-heading-title, .gw-sec .gw-fs-md.elementor-widget-text-editor, .gw-sec .gw-fs-md .elementor-widget-container { font-size: 40px !important; }
}

/* Marquee for the stats band (needs Elementor Pro Custom CSS). Without it the row is static and clipped. */
selector .gw-stats-track { animation: gw-stats-marquee 40s linear infinite; }
selector:hover .gw-stats-track { animation-play-state: paused; }
selector .gw-nowrap { white-space: nowrap; }
@keyframes gw-stats-marquee { from { transform: translateX(0); } to { transform: translateX(calc(-50% - 51.5px)); } }
@media (prefers-reduced-motion: reduce) { selector .gw-stats-track { animation: none; } }

/* FAQ toggle icon circles (needs Elementor Pro Custom CSS). Without it the +/- icons show plain. */
selector .elementor-toggle .elementor-tab-title { display: flex; align-items: center; justify-content: space-between; gap: 24px; }
selector .elementor-toggle .elementor-toggle-icon { order: 2; float: none; flex: 0 0 40px; width: 40px; height: 40px; border: 1px solid #DBDBDB; border-radius: 50%; display: flex; align-items: center; justify-content: center; }
selector .elementor-toggle .elementor-tab-title.elementor-active .elementor-toggle-icon { background: #0074BE; border-color: #0074BE; }
selector .elementor-toggle .elementor-toggle-item { border-bottom: 1px solid rgba(219,219,219,0.3); }
